import os, tempfile
os.chdir(tempfile.mkdtemp())
for name in ('b.pdf', 'A.pdf', 'c.PDF', 'notes.txt'):
    open(name, 'w').close()
pdf_filenames = []
for filename in os.listdir('.'):
    if filename.lower().endswith('.pdf'):
        pdf_filenames.append(filename)
pdf_filenames.sort(key=str.lower)
print(pdf_filenames)

Styles: the kind and the exact name:
import docx
doc = docx.Document()
p = doc.add_paragraph('Quoted words')
try: p.style = 'Quote Char'
except ValueError: print('a paragraph refuses a character style')
try: doc.add_paragraph('x', 'List Number ')
except KeyError: print('style not found: names match exactly')
doc.add_paragraph('x', 'List Number')
print('List Number found:', doc.paragraphs[-1].style.name)

Adding headings:
import docx
doc = docx.Document()
for level in (0, 1, 9):
    h = doc.add_heading('Heading %d' % level, level)
    print('level', level, '->', h.style.name)
try: doc.add_heading('Too deep', 10)
except ValueError: print('level 10 refused: levels are 0 to 9')

Practice program: PDF Paranoia, walk the:
import os, tempfile
os.chdir(tempfile.mkdtemp())
os.makedirs('tree/sub')
for path in ('tree/a.pdf', 'tree/sub/B.PDF', 'tree/c.txt'):
    open(path, 'w').close()
found = []
for folder, dirs, names in os.walk('tree'):
    for name in names:
        if name.lower().endswith('.pdf'):
            found.append(os.path.join(folder, name))
print(sorted(found))
